pat = re.compile(r'^(\S+) (\w+)\s+req=([0-9a-f]{8}) key=(\S+) path=(\S+) status=(\d+) ms=(\d+)$')
recs=[]
for ln in open('service.log'):
    m=pat.match(ln.rstrip())
    ts,lvl,rid,key,path,status,_=m.groups()
